local TabModel = {}function TabModel:new(init)  local o = init or {}  setmetatable(o, self)  self.__index = self  o.binding = o.binding or "bnd_tab_index"  o.action = o.action or "setTabContext"  o.im.Subscribe(o.binding, function()    o:_publishTabIndex()  end  )  o.nav.AddActionHandler(o.action, false, nil, function(action, index)    o.currentTabIndex = index    o:_publishTabIndex()  end  )  return oendfunction TabModel:_publishTabIndex()  if self.currentTabIndex == nil then    return  end  self.im.Publish(self.binding, self.currentTabIndex)endfunction TabModel:finalize()  self.nav.RemoveActionHandler(self.action)  self.im.Unsubscribe(self.binding)endreturn TabModel